SELECT ?zone ?zoneName ?point ?ts WHERE {
  ?point a brick:AirTemperatureSensor .
  ?point brick:hasPropertySymbol ?sym .
  ?point ref:hasTimeseriesId ?ts .
  ?zone rdfs:label ?zoneName .
}

SELECT ?p ?zone ?label WHERE {
  ?p a brick:Zone_Air_Temperature_Sensor .
  ?p brick:pointOf ?zone .
  OPTIONAL { ?zone rdfs:label ?label }
}

SELECT ?p ?o WHERE {
  ?p a brick:Zone_Air_Temperature_Sensor .
  ?p ?s ?o .
  FILTER(!(?s = rdf:type && !(?s = rdf:type))) 
} LIMIT 30

SELECT ?p ?zone ?label ?tsref WHERE {
  ?p a brick:Zone_Air_Temperature_Sensor .
  ?p ?link ?zone .
  FILTER(!IRI(?zone) || !STRSTARTS(STR(?zone), "http://qudt.org") ) .
  FILTER(?zone != ?p) .
  FILTER(!STRSTARTS(STR(?zone), "https://brickschema.org")) .
  FILTER(!STRSTARTS(STR(?zone), "http://qudt.org")) .
  OPTIONAL { ?zone rdfs:label ?label } .
  OPTIONAL { ?p ref:hasExternalReference ?tsref . ?tsref ref:hasTimeseriesId ?tsid . BIND("x" AS ?tsref) }
} LIMIT 10

SELECT ?vav ?zone ?label WHERE {
  ?vav a brick:VAV .
  ?vav brick:hasPart | brick:partOf ?zone .
  OPTIONAL { ?zone rdfs:label ?label }
} LIMIT 5

