import re
txt=open(GRAPH_TTL).read()
blocks=txt.split('\n\n')
info={}
for b in blocks:
    if 'Zone_Air_Temperature_Sensor' in b and 'a brick:Zone_Air_Temperature_Sensor' in b:
        m=re.search(r'bldg:([^ ]+)', b)
        name=m.group(1)
        # pointOf
        pm=re.search(r'bldg:(\w+)\s*(?=;|[.]?\s*$)', b) 
        # find non-sensor bldg references
        zone=None; tsref=None; tsid=None; label=None
        for line in b.split(';'):
            ls=line.strip()
            if 'pointOf' in ls or 'isPointOf' in ls:
                z=re.search(r'bldg:(\w+)$', ls)
                if z: zone=z.group(1)
            if 'hasExternalReference' in ls:
                t=re.search(r'tsref:([a-f0-9-]+)', ls)
                if t: tsref=t.group(1)
            if 'hasTimeseriesId' in ls:
                t=re.search(r'([a-f0-9-]{36})', ls)
                if t: tsid=t.group(1)
            if 'rdfs:label' in ls:
                l=re.search(r'"([^"]+)"', ls)
                if l: label=l.group(1)
        info[name]={'zone':zone,'tsref':tsref,'tsid':tsid,'label':label}
import json
print(json.dumps(info, indent=1))
print(len(info))

